import {readFileSync} from 'node:fs'
import {resolve} from 'node:path'
import {runInNewContext} from 'node:vm'
import * as session from '../../mcp/session'
import {afterEach, beforeEach, describe, expect, it, vi} from 'vitest'
import {forgetSession, giveThisPageASessionForTesting} from '../../mcp/session'
import {retainedSelectionMediaType, type RetainedSelectionSource} from './wire'
import {retainedResponseChunks, retainedSelectionClient, RetainedReviewError} from './client'

// Independent handwritten shared bytes, never generated by the writer under test.
interface Fixture {
 file: string; source: RetainedSelectionSource; bytes: number; indexSha256: string
 rows: {index: number; id: string; inputHex: string; inputSha256: string; inputBytes: number}[]
}
const root = resolve(import.meta.dirname, '../../../../internal/desk/testdata/retained-selection-wire')
const fixtures = (JSON.parse(readFileSync(resolve(root, 'manifest.json'), 'utf8')) as {positives: Fixture[]}).positives
const f = fixtures[0]!
const raw = (fixture = f) => Uint8Array.from(Buffer.from(readFileSync(resolve(root, fixture.file), 'utf8').trim(), 'hex'))
const input = (fixture = f) => Uint8Array.from(Buffer.from(fixture.rows[0]!.inputHex, 'hex'))
function response(bytes: Uint8Array, media = retainedSelectionMediaType, headers: Record<string, string> = {}) {
 return new Response(bytes as BodyInit, {headers: {'Content-Type': media, 'Content-Length': String(bytes.length), ...headers}})
}
function deferred<T>() {
 let resolve!: (value: T) => void
 const promise = new Promise<T>(yes => { resolve = yes })
 return {promise, resolve}
}
beforeEach(() => { sessionStorage.removeItem('jpack.active-desk'); giveThisPageASessionForTesting('a'.repeat(48)) })
afterEach(() => { vi.restoreAllMocks(); vi.unstubAllGlobals(); sessionStorage.removeItem('jpack.active-desk') })

describe('inactive captured retained selection client', () => {
 it.each(['source-copy','json','encoding'] as const)('capture allocation failure at %s is resource before HTTP and needs explicit retry', async phase => {
  const fetch = vi.fn().mockImplementation(() => response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient()
  const source = {...f.source, recordIds: [...f.source.recordIds]}
  const fail = () => { throw new RangeError('private allocation detail') }
  const injection = phase === 'source-copy' ? vi.spyOn(source.recordIds, Symbol.iterator).mockImplementationOnce(fail)
   : phase === 'json' ? vi.spyOn(JSON, 'stringify').mockImplementationOnce(fail)
   : vi.spyOn(TextEncoder.prototype, 'encode').mockImplementationOnce(fail)
  // Capture is synchronous before prepare's first await; restore the injected
  // allocator before assertions or the later explicit retry can use it.
  const pending = client.prepare(source)
  injection.mockRestore()
  await expect(pending).rejects.toMatchObject({kind: 'resource', message: 'Retained review resource.'})
  await Promise.resolve()
  expect(fetch).not.toHaveBeenCalled()
  await expect(client.prepare(f.source)).resolves.toMatchObject({indexSha256: f.indexSha256})
  expect(fetch).toHaveBeenCalledTimes(1)
 })
 it('capture serialization shape failure stays invalid-request before HTTP', async () => {
  const fetch = vi.fn()
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient()
  const injection = vi.spyOn(JSON, 'stringify').mockImplementationOnce(() => { throw new TypeError('private invalid source detail') })
  const pending = client.prepare(f.source)
  injection.mockRestore()
  await expect(pending).rejects.toMatchObject({kind: 'invalid-request', message: 'Retained review invalid-request.'})
  expect(fetch).not.toHaveBeenCalled()
 })
 it('uses the captured legitimate session and closed source-only request, never payload auth', async () => {
  const fetch = vi.fn().mockResolvedValue(response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient()
  const view = await client.prepare({...f.source, recordIds: [...f.source.recordIds]})
  const [path, init] = fetch.mock.calls[0] as [string, RequestInit]
  expect(path).toBe(`/api/input-preparations/${f.source.preparationId}/prepare`)
  expect(init).toMatchObject({method: 'POST', redirect: 'error', credentials: 'omit', headers: {Authorization: `Bearer ${'a'.repeat(48)}`, Accept: retainedSelectionMediaType, 'If-Match': f.source.revision}})
  expect(JSON.parse(String(init.body))).toEqual({recordIds: f.source.recordIds})
  expect(view.indexSha256).toBe(f.indexSha256)
  expect(Object.isFrozen(view.rows[0])).toBe(true)
  expect(Object.isFrozen(view.header.conversionContract.spec)).toBe(true)
 })
 const invalidHeaders: Record<string, string>[] = [
  {'Content-Type': `${retainedSelectionMediaType}; charset=utf-8`},
  {'Content-Length': '01029'}, {'Content-Length': '+1029'}, {'Content-Length': '1e3'},
  {'Content-Length': '9007199254740992'}, {'Content-Encoding': 'gzip'}, {'Content-Encoding': 'Identity'}
 ]
 it.each(invalidHeaders)('refuses nonexact success headers %j', async headers => {
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response(raw(), retainedSelectionMediaType, headers)))
  await expect((await retainedSelectionClient()).prepare(f.source)).rejects.toMatchObject({kind: 'invalid-response'})
 })
 it('does not consume aggregate text/json/blob and accepts byte-by-byte backpressure', async () => {
  const bytes = raw(); let at = 0
  const body = new ReadableStream<Uint8Array>({pull(controller) { if (at === bytes.length) controller.close(); else controller.enqueue(bytes.subarray(at, ++at)) }}, {highWaterMark: 0})
  const answer = new Response(body, {headers: {'Content-Type': retainedSelectionMediaType, 'Content-Length': String(bytes.length)}})
  answer.text = vi.fn(() => { throw Error('aggregate text forbidden') })
  answer.json = vi.fn(() => { throw Error('aggregate json forbidden') })
  answer.blob = vi.fn(() => { throw Error('aggregate blob forbidden') })
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(answer))
  expect((await (await retainedSelectionClient()).prepare(f.source)).rows).toHaveLength(1)
  expect(answer.text).not.toHaveBeenCalled(); expect(answer.json).not.toHaveBeenCalled(); expect(answer.blob).not.toHaveBeenCalled()
  expect(body.locked).toBe(false)
 })
 it('waits for actual EOF even after the complete valid end frame', async () => {
  const eof = deferred<void>()
  let sent = false
  const body = new ReadableStream<Uint8Array>({async pull(c) { if (!sent) { sent = true; c.enqueue(raw()) } else { await eof.promise; c.close() } }}, {highWaterMark: 0})
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(body, {headers: {'Content-Type': retainedSelectionMediaType, 'Content-Length': String(f.bytes)}})))
  let settled = false
  const pending = (await retainedSelectionClient()).prepare(f.source).then(view => { settled = true; return view })
  // A macrotask observes the intentionally blocked EOF, not a timing threshold.
  await new Promise(resolve => setTimeout(resolve, 0))
  expect(settled).toBe(false)
  eof.resolve()
  await expect(pending).resolves.toMatchObject({indexSha256: f.indexSha256})
 })
 it.each(['late-error','trailer','truncated'] as const)('rejects %s without publishing a view and releases the reader', async fault => {
  let sent = false
  const bytes = raw()
  const body = new ReadableStream<Uint8Array>({pull(c) {
   if (!sent) { sent = true; c.enqueue(fault === 'truncated' ? bytes.subarray(0, bytes.length - 1) : bytes); return }
   if (fault === 'late-error') c.error(Error('late fault'))
   else { if (fault === 'trailer') c.enqueue(Uint8Array.of(0)); c.close() }
  }}, {highWaterMark: 0})
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(body, {headers: {'Content-Type': retainedSelectionMediaType, 'Content-Length': String(bytes.length)}})))
  await expect((await retainedSelectionClient()).prepare(f.source)).rejects.toBeInstanceOf(RetainedReviewError)
  expect(body.locked).toBe(false)
 })
 it('abort cancels a pending pull and releases its lock even when cancellation never settles', async () => {
  const cancelled = vi.fn(() => new Promise<void>(() => {}))
  const body = new ReadableStream<Uint8Array>({pull: () => new Promise<void>(() => {}), cancel: cancelled}, {highWaterMark: 0})
  const abort = new AbortController(), iterator = retainedResponseChunks(new Response(body), abort.signal)
  const pending = iterator.next()
  abort.abort()
  await expect(pending).rejects.toMatchObject({kind: 'cancelled'})
  expect(cancelled).toHaveBeenCalledTimes(1)
  expect(body.locked).toBe(false)
 })
 it('borrows genuine foreign Uint8Array spans into the codec realm without copying', async () => {
  const foreign = runInNewContext('new Uint8Array([9, 123, 125, 8]).subarray(1, 3)') as Uint8Array
  expect(foreign instanceof Uint8Array).toBe(false)
  const body = new ReadableStream<Uint8Array>({start(c) { c.enqueue(foreign); c.close() }})
  const iterator = retainedResponseChunks(new Response(body), new AbortController().signal)
  const next = await iterator.next()
  expect(next.value).toBeInstanceOf(Uint8Array)
  const borrowed = next.value as Uint8Array
  expect([...borrowed]).toEqual([123,125])
  expect(borrowed.buffer).toBe(foreign.buffer)
  expect(borrowed.byteOffset).toBe(foreign.byteOffset)
  await iterator.return(undefined)
  expect(body.locked).toBe(false)
 })
 it('keeps genuine local browser stream bytes unchanged', async () => {
  const bytes = Uint8Array.of(123,125)
  const body = new ReadableStream<Uint8Array>({start(c) { c.enqueue(bytes); c.close() }})
  const iterator = retainedResponseChunks(new Response(body), new AbortController().signal)
  expect((await iterator.next()).value).toBe(bytes)
  await iterator.return(undefined)
 })
 it.each(['array','dataview','clamped','forged-tag'] as const)('refuses non-Uint8Array stream chunks: %s', async kind => {
  const forged = new Uint16Array([123,125])
  Object.defineProperty(forged, Symbol.toStringTag, {value: 'Uint8Array'})
  const value = {array: [123,125], dataview: new DataView(new ArrayBuffer(2)), clamped: new Uint8ClampedArray([123,125]), 'forged-tag': forged}[kind]
  const body = new ReadableStream<Uint8Array>({start(c) { c.enqueue(value as unknown as Uint8Array); c.close() }})
  await expect(retainedResponseChunks(new Response(body), new AbortController().signal).next()).rejects.toMatchObject({kind: 'invalid-response'})
  expect(body.locked).toBe(false)
 })
 it('does not pull an already cancelled adapter and releases its lock', async () => {
  const pull = vi.fn(), cancel = vi.fn()
  const body = new ReadableStream<Uint8Array>({pull, cancel}, {highWaterMark: 0})
  const abort = new AbortController(); abort.abort()
  await expect(retainedResponseChunks(new Response(body), abort.signal).next()).rejects.toMatchObject({kind: 'cancelled'})
  expect(pull).not.toHaveBeenCalled(); expect(cancel).toHaveBeenCalledTimes(1)
  expect(body.locked).toBe(false)
 })
 it('consumer return cancels once without waiting for source cancellation', async () => {
  const pull = vi.fn((c: ReadableStreamDefaultController<Uint8Array>) => c.enqueue(Uint8Array.of(123,125)))
  const cancel = vi.fn(() => new Promise<void>(() => {}))
  const body = new ReadableStream<Uint8Array>({pull, cancel}, {highWaterMark: 0})
  const iterator = retainedResponseChunks(new Response(body), new AbortController().signal)
  await iterator.next()
  await iterator.return(undefined)
  expect(pull).toHaveBeenCalledTimes(1); expect(cancel).toHaveBeenCalledTimes(1)
  expect(body.locked).toBe(false)
 })
 it('read rejection releases the lock and keeps source prose private', async () => {
  const body = new ReadableStream<Uint8Array>({pull(c) { c.error(Error('private source fault')) }}, {highWaterMark: 0})
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(body, {headers: {'Content-Type': retainedSelectionMediaType, 'Content-Length': String(f.bytes)}})))
  await expect((await retainedSelectionClient()).prepare(f.source)).rejects.toMatchObject({kind: 'unavailable', message: 'Retained review unavailable.'})
  expect(body.locked).toBe(false)
 })
 it('terminal session end at the deskFetch await boundary aborts before effective dispatch', async () => {
  const original = session.sessionBearer
  let calls = 0, effectiveDispatches = 0
  vi.spyOn(session, 'sessionBearer').mockImplementation(async () => {
   const bearer = await original()
   // Capture, scope current, then deskFetch's own awaited session lookup.
   if (++calls === 3) forgetSession()
   return bearer
  })
  const fetch = vi.fn((_path: string, init: RequestInit) => {
   if (init.signal?.aborted) return Promise.reject(new DOMException('aborted', 'AbortError'))
   effectiveDispatches++
   return Promise.resolve(response(raw()))
  })
  vi.stubGlobal('fetch', fetch)
  await expect((await retainedSelectionClient()).prepare(f.source)).rejects.toBeInstanceOf(RetainedReviewError)
  expect(calls).toBe(3); expect(effectiveDispatches).toBe(0)
  expect(fetch).toHaveBeenCalledTimes(1)
  expect((fetch.mock.calls[0]![1] as RequestInit).signal?.aborted).toBe(true)
 })
 it('cancelled row digest holds the document slot across clients until settlement, with explicit retry only', async () => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw())).mockResolvedValueOnce(response(input(), 'application/json')).mockResolvedValueOnce(response(input(), 'application/json'))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source), other = await retainedSelectionClient()
  const digest = deferred<ArrayBuffer>(), entered = deferred<void>()
  const spy = vi.spyOn(crypto.subtle, 'digest').mockImplementationOnce(() => { entered.resolve(); return digest.promise })
  const decode = vi.spyOn(TextDecoder.prototype, 'decode')
  const abort = new AbortController(), pending = client.read(view, 0, abort.signal)
  const outcome = expect(pending).rejects.toMatchObject({kind: 'cancelled'})
  await entered.promise
  abort.abort()
  await expect(client.read(view, 0)).rejects.toMatchObject({kind: 'resource'})
  await expect(other.prepare(f.source)).rejects.toMatchObject({kind: 'resource'})
  expect(fetch).toHaveBeenCalledTimes(2); expect(spy).toHaveBeenCalledTimes(1)
  digest.resolve(Uint8Array.from(Buffer.from(f.rows[0]!.inputSha256, 'hex')).buffer as ArrayBuffer)
  await outcome
  expect(fetch).toHaveBeenCalledTimes(2); expect(decode).not.toHaveBeenCalled()
  await expect(client.read(view, 0)).resolves.toMatchObject({text: '{}'})
  expect(fetch).toHaveBeenCalledTimes(3)
 })
 it('digest rejection releases the document slot for the next explicit read', async () => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw())).mockResolvedValueOnce(response(input(), 'application/json')).mockResolvedValueOnce(response(input(), 'application/json'))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source)
  vi.spyOn(crypto.subtle, 'digest').mockRejectedValueOnce(new RangeError('private allocation fault'))
  await expect(client.read(view, 0)).rejects.toMatchObject({kind: 'resource', message: 'Retained review resource.'})
  expect(fetch).toHaveBeenCalledTimes(2)
  await expect(client.read(view, 0)).resolves.toMatchObject({text: '{}'})
  expect(fetch).toHaveBeenCalledTimes(3)
 })
 it('cancelled initial digest holds ownership until settlement and never starts queued preparation', async () => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw())).mockResolvedValueOnce(response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), abort = new AbortController()
  const digest = deferred<ArrayBuffer>(), entered = deferred<void>()
  vi.spyOn(crypto.subtle, 'digest').mockImplementationOnce(() => { entered.resolve(); return digest.promise })
  const pending = client.prepare(f.source, abort.signal)
  const outcome = expect(pending).rejects.toMatchObject({kind: 'cancelled'})
  await entered.promise
  abort.abort()
  await expect(client.prepare(f.source)).rejects.toMatchObject({kind: 'resource'})
  expect(fetch).toHaveBeenCalledTimes(1)
  // Handwritten compact fixture's selection-domain SHA, not a codec result.
  digest.resolve(Uint8Array.from(Buffer.from('08a4a2fee43dde436494d722223a34869d1c9c3d347faaffac2b44a1f00f4ae5', 'hex')).buffer as ArrayBuffer)
  await outcome
  expect(fetch).toHaveBeenCalledTimes(1)
  await expect(client.prepare(f.source)).resolves.toMatchObject({indexSha256: f.indexSha256})
  expect(fetch).toHaveBeenCalledTimes(2)
 })
 it('session/desk changes cannot send read or close with a replacement identity', async () => {
  const fetch = vi.fn().mockResolvedValue(response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source)
  giveThisPageASessionForTesting('b'.repeat(48))
  await expect(client.read(view, 0)).rejects.toMatchObject({kind: 'session-ended'})
  await expect(client.close(view)).rejects.toMatchObject({kind: 'session-ended'})
  expect(fetch).toHaveBeenCalledTimes(1)
  giveThisPageASessionForTesting('a'.repeat(48))
  sessionStorage.setItem('jpack.active-desk', 'c'.repeat(32))
  await expect(client.prepare(f.source)).rejects.toMatchObject({kind: 'session-ended'})
  expect(fetch).toHaveBeenCalledTimes(1)
 })
 it('revocation interrupts an in-flight stream and does not require close HTTP', async () => {
  let cancelled = 0
  const body = new ReadableStream<Uint8Array>({pull: () => new Promise<void>(() => {}), cancel() { cancelled++ }}, {highWaterMark: 0})
  const fetch = vi.fn().mockResolvedValue(new Response(body, {headers: {'Content-Type': retainedSelectionMediaType, 'Content-Length': String(f.bytes)}}))
  vi.stubGlobal('fetch', fetch)
  const pending = (await retainedSelectionClient()).prepare(f.source)
  await new Promise(resolve => setTimeout(resolve, 0))
  forgetSession()
  await expect(pending).rejects.toBeInstanceOf(RetainedReviewError)
  expect(cancelled).toBe(1); expect(body.locked).toBe(false); expect(fetch).toHaveBeenCalledTimes(1)
 })
 it('mount reads only the owned sealed index and preserves lexical input without parsing', async () => {
  const fixture = fixtures.find(x => x.file === 'lexical.wire.hex')!
  const fetch = vi.fn().mockResolvedValueOnce(response(raw(fixture))).mockResolvedValueOnce(response(input(fixture), 'application/json'))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(fixture.source)
  const mounted = await client.read(view, 0)
  expect(mounted.text).toBe(new TextDecoder('utf-8', {ignoreBOM: true}).decode(input(fixture)))
  const init = fetch.mock.calls[1]![1] as RequestInit
  expect(JSON.parse(String(init.body))).toEqual({viewId: view.header.viewId, indexSha256: fixture.indexSha256, index: 0, id: fixture.rows[0]!.id})
  expect(init.headers).toMatchObject({'If-Match': fixture.indexSha256})
  await expect(client.read({...view}, 0)).rejects.toMatchObject({kind: 'invalid-request'})
 })
 it.each([
  [409, 'review-not-ready', 'review-not-ready'], [410, 'review-unavailable', 'expired'], [503, 'review-busy', 'resource']
 ])('classifies %i %s with no automatic prepare or read retry', async (status, code, kind) => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw())).mockResolvedValueOnce(new Response(JSON.stringify({code, error: 'private server prose'}), {status: Number(status)}))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source)
  await expect(client.read(view, 0)).rejects.toMatchObject({kind})
  expect(fetch).toHaveBeenCalledTimes(2)
 })
 it('rejects short, extra and hash-changed row bytes', async () => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source)
  for (const bytes of [Uint8Array.of(123), Uint8Array.of(123,125,0), Uint8Array.of(91,93)]) {
   fetch.mockResolvedValueOnce(response(bytes, 'application/json', {'Content-Length': String(f.rows[0]!.inputBytes)}))
   await expect(client.read(view, 0)).rejects.toMatchObject({kind: 'invalid-response'})
  }
 })
 it('freezes selection before the request and refuses malformed source before sending', async () => {
  const fetch = vi.fn().mockResolvedValue(response(raw()))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), source = {...f.source, recordIds: [...f.source.recordIds]}
  const pending = client.prepare(source)
  source.recordIds[0] = 'changed'
  await expect(pending).resolves.toMatchObject({indexSha256: f.indexSha256})
  await expect(client.prepare({...f.source, recordIds: ['r','r']})).rejects.toMatchObject({kind: 'invalid-request'})
  expect(fetch).toHaveBeenCalledTimes(1)
 })
 it('normal close sends only the exact owned reference with current captured auth and is idempotent', async () => {
  const fetch = vi.fn().mockResolvedValueOnce(response(raw())).mockResolvedValueOnce(new Response(null, {status: 204}))
  vi.stubGlobal('fetch', fetch)
  const client = await retainedSelectionClient(), view = await client.prepare(f.source)
  await client.close(view); await client.close(view)
  expect(fetch).toHaveBeenCalledTimes(2)
  const [path, init] = fetch.mock.calls[1] as [string, RequestInit]
  expect(path).toBe(`/api/input-preparations/${f.source.preparationId}/prepared-view-close`)
  expect(JSON.parse(String(init.body))).toEqual({viewId: view.header.viewId, indexSha256: view.indexSha256})
  expect(init).toMatchObject({credentials: 'omit', redirect: 'error', headers: {Authorization: `Bearer ${'a'.repeat(48)}`}})
  await expect(client.read(view, 0)).rejects.toMatchObject({kind: 'invalid-request'})
 })
 it('an already aborted explicit action sends no preparation', async () => {
  const fetch = vi.fn()
  vi.stubGlobal('fetch', fetch)
  const abort = new AbortController(); abort.abort()
  await expect((await retainedSelectionClient()).prepare(f.source, abort.signal)).rejects.toMatchObject({kind: 'cancelled'})
  expect(fetch).not.toHaveBeenCalled()
 })

})
